type Scope={tenant:string;property:string;invoice:string;actor:string};
function amount(v:unknown){if(typeof v!=='string'||!/^(0|[1-9][0-9]{0,11})$/.test(v))throw Error('Invalid credit amount.');return BigInt(v);}
export function readInvoiceCreditOptions(value:unknown,scope:Scope){
 const r=value as Record<string,unknown>;if(!r||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.invoice_id!==scope.invoice||r.actor_id!==scope.actor||r.currency!=='USD'||r.complete!==true||!Array.isArray(r.lines)||r.lines.length<1||r.lines.length>10000)throw Error('Credit review scope changed.');
 const outstanding=amount(r.invoice_outstanding_minor);let last=0;
 const lines=r.lines.map(value=>{const l=value as Record<string,unknown>;if(!l||typeof l.line_number!=='number'||!Number.isInteger(l.line_number)||l.line_number!==last+1||typeof l.description!=='string'||!l.description.trim()||l.description.length>500||typeof l.category!=='string'||l.category.length>100)throw Error('Invalid credit source line.');last=l.line_number;const issued=amount(l.issued_minor),credited=amount(l.credited_minor),available=amount(l.available_minor);if(issued===BigInt(0)||issued-credited!==available)throw Error('Credit source amounts do not reconcile.');return {line_number:last,description:l.description,category:l.category,issued_minor:issued.toString(),credited_minor:credited.toString(),available_minor:available.toString()};});
 return {outstanding_minor:outstanding.toString(),lines};
}
export function selectInvoiceCredit(value:unknown,scope:Scope,selections:{line_number:number;amount_minor:string}[]){const review=readInvoiceCreditOptions(value,scope),seen=new Set<number>();let total=BigInt(0);if(!Array.isArray(selections)||!selections.length||selections.length>10000)throw Error('Select at least one credited charge.');const lines=selections.map(line=>{const original=review.lines.find(l=>l.line_number===line.line_number),selected=amount(line.amount_minor);if(!original||seen.has(line.line_number)||selected===BigInt(0)||selected>BigInt(original.available_minor))throw Error('Credit exceeds the remaining original charge.');seen.add(line.line_number);total+=selected;return {line_number:line.line_number,amount_minor:selected.toString()};});if(total>BigInt(review.outstanding_minor))throw Error('Credit exceeds unpaid invoice balance. Reverse payment allocations first if needed.');return {lines,amount_minor:total.toString()};}
